function dump(n, d) {
  const o = { t: n.type, n: n.name, id: n.id, w: Math.round(n.width*10)/10, h: Math.round(n.height*10)/10 };
  try { if ("fills" in n && n.fills !== figma.mixed && Array.isArray(n.fills) && n.fills.length) o.f = JSON.parse(JSON.stringify(n.fills)); } catch(e){}
  try { if ("strokes" in n && n.strokes !== figma.mixed && Array.isArray(n.strokes) && n.strokes.length) o.s = JSON.parse(JSON.stringify(n.strokes)); } catch(e){}
  try { if ("strokes" in n && n.strokeWeight) o.sw = n.strokeWeight; } catch(e){}
  try { if ("cornerRadius" in n && typeof n.cornerRadius === "number") o.r = n.cornerRadius; } catch(e){}
  if (n.type === "TEXT") { o.chars = n.characters; o.fs = n.fontSize; o.ff = (typeof n.fontName === "object" && n.fontName !== figma.mixed) ? (n.fontName.family + ":" + n.fontName.style) : "mixed"; }
  if (d > 0 && "children" in n) o.c = n.children.map(c => dump(c, d-1));
  return o;
}

